module top(input clk,rst,start,ack, output reg busy,done);
  reg [1:0] state;
  localparam IDLE=0, RUN=1, DONE=2;
  always @(posedge clk) begin
    if(rst) state<=IDLE;
    else case(state)
      IDLE: if(start) state<=RUN;
      RUN: state<=DONE;
      DONE: if(ack) state<=IDLE;
      default: state<=IDLE;
    endcase
  end
  always @* begin busy=0; done=0;
    case(state) RUN: busy=1; DONE: done=1; default: begin end endcase
  end
endmodule

testbench:
`timescale 1ns/1ps
module tb;
reg clk=0,rst=1,start=0,ack=0; wire busy,done;
always #5 clk=~clk;
top dut(clk,rst,start,ack,busy,done);
initial begin
 $dumpfile("dump.vcd"); $dumpvars(0,tb);
 @(posedge clk); #1; if({busy,done}!==0) $fatal(1,"reset");
 @(negedge clk); rst=0; start=1;
 @(posedge clk); #1; if(!busy || done) $fatal(1,"RUN");
 @(negedge clk); start=0;
 @(posedge clk); #1; if(busy || !done) $fatal(1,"DONE");
 @(negedge clk); ack=1;
 @(posedge clk); #1; if(busy || done) $fatal(1,"IDLE");
 $display("FSM PASS"); $finish;
end
endmodule

