// Educational 8-bit accumulator CPU. Not a RISC-V implementation.
// instruction[9:8]: 00 LOAD, 01 ADD, 10 XOR, 11 HALT.
module top(input clk,rst, input [9:0] instruction,
           output reg [7:0] acc, output reg [3:0] pc, output reg halted);
 always @(posedge clk) begin
  if(rst) begin acc<=0; pc<=0; halted<=0; end
  else if(!halted) begin
   case(instruction[9:8])
    2'b00: acc<=instruction[7:0];
    2'b01: acc<=acc+instruction[7:0];
    2'b10: acc<=acc^instruction[7:0];
    2'b11: halted<=1;
   endcase
   if(instruction[9:8]!=2'b11) pc<=pc+1'b1;
  end
 end
endmodule

testbench:
`timescale 1ns/1ps
module tb;
reg clk=0,rst=1; reg [9:0] instruction; wire [7:0] acc;
wire [3:0] pc; wire halted;
always #5 clk=~clk;
top dut(clk,rst,instruction,acc,pc,halted);
always @* case(pc)
 0: instruction={2'b00,8'd5};
 1: instruction={2'b01,8'd7};
 2: instruction={2'b10,8'd3};
 default: instruction={2'b11,8'd0};
endcase
initial begin
 $dumpfile("dump.vcd"); $dumpvars(0,tb);
 @(negedge clk); rst=0;
 repeat(4) @(posedge clk); #1;
 if(acc!==8'd15 || pc!==3 || halted!==1) $fatal(1,"CPU result");
 $display("CPU PASS"); #10; $finish;
end
endmodule
